<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {api,apiBlob,uploadEvidence,useLoad,useCommand,PageHeader,Feedback,EmptyState,StatusBadge,money,session,type Aftersale,type Materials} from '@tradeflow/ui'
import {useRows,text,permits,row} from '../data'
import Pagination from '../components/Pagination.vue'
import RecordDetail from '../components/RecordDetail.vue'
const list=useRows(()=>'/api/v1/merchant/aftersales','cursor')
const no=ref(''),visible=ref(false),action=ref(''),reason=ref(''),evidenceKeys=ref<string[]>([]),uploading=ref(false),localError=ref(''),notice=ref('')
const detail=useLoad<Aftersale>(signal=>api('/api/v1/merchant/aftersales/'+encodeURIComponent(no.value),{signal}))
const materials=useLoad<Materials>(signal=>api('/api/v1/merchant/aftersales/'+encodeURIComponent(no.value)+'/materials',{signal}))
const command=useCommand('admin-aftersales')
const dispositions=ref<Record<string,string>>({})
const dispositionOptions=[{value:'SALEABLE',label:'可再售'},{value:'QUARANTINE',label:'待检隔离'},{value:'DAMAGED',label:'残次保留'},{value:'SCRAPPED',label:'报损'}]
const unitKey=(item:string,unit:number)=>item+':'+unit
let generation=0
onBeforeUnmount(()=>{generation++})
async function open(value:unknown){const g=++generation;no.value=String(value);visible.value=true;action.value='';reason.value='';evidenceKeys.value=[];dispositions.value={};localError.value='';notice.value='';detail.clear();materials.clear();await detail.reload();if(g===generation&&detail.data.value&&permits(detail.data.value,'VIEW_MATERIALS'))await materials.reload()}
function close(){generation++;uploading.value=false;visible.value=false;action.value='';detail.clear();materials.clear();evidenceKeys.value=[]}
function choose(value:string){generation++;uploading.value=false;action.value=value;reason.value='';evidenceKeys.value=[];dispositions.value={};localError.value=''}
/** 上传证据只使用当前弹窗代际，账号/资源变化后丢弃迟到响应；不持久化正文和文件内容。 */
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const g=generation;uploading.value=true;localError.value='';try{const result=await uploadEvidence(file);if(g===generation)evidenceKeys.value.push(result.objectKey)}catch(e){if(g===generation)localError.value=e instanceof Error?e.message:'证据上传失败'}finally{if(g===generation)uploading.value=false;(event.target as HTMLInputElement).value=''}}
async function download(key:string){const g=generation;try{const blob=await apiBlob('/api/v1/evidence-files/'+encodeURIComponent(key));if(g!==generation)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=key;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(g===generation)localError.value=e instanceof Error?e.message:'证据读取失败'}}
/** 原申请金额不可改写；整单验收与拒收不能部分提交，拒收必须绑定实际上传证据。明确FAILED且服务器允许时才重试退款。 */
async function submit(){const current=detail.data.value;if(!current)return;localError.value='';if(!reason.value.trim()){localError.value='请填写本次业务处理原因';return}if(action.value==='REFUSED'&&!evidenceKeys.value.length){localError.value='拒收必须上传至少一份证据';return}
const selectedAction=action.value,g=generation,target=no.value;let endpoint='',body:Record<string,unknown>={reason:reason.value.trim()};if(selectedAction==='APPROVE'||selectedAction==='REJECT'){if(!permits(current,selectedAction))return;endpoint='review';body.approved=selectedAction==='APPROVE'}else if(selectedAction==='ACCEPTED'||selectedAction==='REFUSED'){if(!permits(current,'RETURN_INSPECTION'))return;endpoint='return-inspection';body={...body,accepted:selectedAction==='ACCEPTED',evidenceKeys:[...evidenceKeys.value]};if(selectedAction==='ACCEPTED'){const allocations=materials.data.value?.allocations;if(!allocations?.length||allocations.some(a=>!dispositions.value[unitKey(a.orderItemId,a.unitNo)])){localError.value='请为每一购买件明确选择库存处置，未选择不会默认可再售';return}body.dispositions=allocations.map(a=>({orderItemId:a.orderItemId,unitNo:a.unitNo,disposition:dispositions.value[unitKey(a.orderItemId,a.unitNo)]}))}}else{if(current.refundStatus!=='FAILED'||!permits(current,'RETRY_REFUND'))return;endpoint='retry-refund'}const path='/api/v1/merchant/aftersales/'+encodeURIComponent(target)+'/'+endpoint;const result=await command.run(endpoint+':'+target,body,key=>api(path,{method:'POST',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g!==generation)return;action.value='';notice.value='处理请求已返回；退款和退货入库可能继续异步执行，请刷新核对真实进度。';await detail.reload();await materials.reload();await list.reload()}
watch(()=>session.user?.userId,()=>{close();list.clear();notice.value='';uploading.value=false})
onMounted(()=>list.reload())
</script>
<template><PageHeader title="售后协作" description="审核原申请、核对退货材料，依照服务器允许的动作处理。"/><section class="panel"><div class="toolbar"><h2>所属售后</h2><ElButton :loading="list.loading.value" @click="list.reload">刷新列表</ElButton></div><Feedback :loading="list.loading.value" :error="list.error.value"/><template v-if="!list.loading.value&&!list.error.value"><EmptyState v-if="!list.items.value.length" title="当前页暂无售后"/><ElTable v-else :data="list.items.value"><ElTableColumn label="售后编号" min-width="290"><template #default="{row}">{{text(row.aftersaleNo)}}</template></ElTableColumn><ElTableColumn label="类型" min-width="150"><template #default="{row}">{{text(row.type)}}</template></ElTableColumn><ElTableColumn label="状态" width="145"><template #default="{row}"><StatusBadge :status="text(row.status)"/></template></ElTableColumn><ElTableColumn label="申请金额" width="120"><template #default="{row}">{{row.amountCents==null?'待确认':money(Number(row.amountCents))}}</template></ElTableColumn><ElTableColumn label="退款状态" width="140"><template #default="{row}"><StatusBadge :status="text(row.refundStatus)"/></template></ElTableColumn><ElTableColumn label="操作" width="120"><template #default="{row}"><ElButton @click="open(row.aftersaleNo)">查看处理</ElButton></template></ElTableColumn></ElTable></template><Pagination :page="list.page.value" :count="list.items.value.length" :has-next="list.hasNext.value" :loading="list.loading.value" @change="list.change"/></section>
<ElDialog :model-value="visible" title="售后详情与材料" width="860px" @close="close"><Feedback :loading="detail.loading.value" :error="detail.error.value"/><template v-if="detail.data.value"><p class="mono">{{detail.data.value.aftersaleNo}}</p><dl class="detail-grid"><div><dt>售后状态</dt><dd><StatusBadge :status="detail.data.value.status"/></dd></div><div><dt>原申请金额</dt><dd>{{detail.data.value.amountCents==null?'待确认':money(detail.data.value.amountCents)}}</dd></div><div><dt>退款状态</dt><dd><StatusBadge :status="detail.data.value.refundStatus"/></dd></div><div><dt>申请类型</dt><dd>{{detail.data.value.type}}</dd></div><div><dt>订单编号</dt><dd>{{detail.data.value.orderNo}}</dd></div><div><dt>申请原因</dt><dd>{{detail.data.value.reason}}</dd></div></dl><p v-if="detail.data.value.lastError" class="error-note">{{detail.data.value.lastError}}</p>
<h3 class="section-title">购买件分配与证据</h3><Feedback :loading="materials.loading.value" :error="materials.error.value"/><template v-if="materials.data.value"><ElTable :data="materials.data.value.allocations"><ElTableColumn prop="orderItemId" label="订单项" min-width="200"/><ElTableColumn prop="unitNo" label="购买件序号" width="120"/><ElTableColumn label="分配金额" width="140"><template #default="{row}">{{money(row.amountCents)}}</template></ElTableColumn></ElTable><p v-if="!materials.data.value.evidence.length" class="muted">暂无申请证据</p><div v-for="e in materials.data.value.evidence" :key="e.objectKey" class="toolbar"><span>{{e.purpose}} · {{e.objectKey}}</span><ElButton @click="download(e.objectKey)">下载证据</ElButton></div><p v-if="materials.data.value.returnDeadline" class="notice">退货截止：{{materials.data.value.returnDeadline}}</p><h3 class="section-title">退货物流</h3><RecordDetail v-if="materials.data.value.shipment" :value="row(materials.data.value.shipment)"/><p v-else class="muted">暂无退货物流</p><h3 class="section-title">验收记录</h3><RecordDetail v-if="materials.data.value.inspection" :value="row(materials.data.value.inspection)"/><p v-else class="muted">暂无验收记录</p></template>
<p v-if="notice" class="notice" role="status">{{notice}}</p><div class="inline-actions"><ElButton v-if="permits(detail.data.value,'APPROVE')" type="primary" @click="choose('APPROVE')">通过原申请</ElButton><ElButton v-if="permits(detail.data.value,'REJECT')" @click="choose('REJECT')">拒绝申请</ElButton><ElButton v-if="permits(detail.data.value,'RETURN_INSPECTION')" type="primary" @click="choose('ACCEPTED')">认可退货并登记处置</ElButton><ElButton v-if="permits(detail.data.value,'RETURN_INSPECTION')" @click="choose('REFUSED')">整单拒收</ElButton><ElButton v-if="detail.data.value.refundStatus==='FAILED'&&permits(detail.data.value,'RETRY_REFUND')" @click="choose('RETRY_REFUND')">重试明确失败退款</ElButton><ElButton @click="detail.reload();materials.reload()">刷新详情</ElButton></div>
<ElForm v-if="action" class="panel" label-position="top" @submit.prevent="submit"><h3>{{({APPROVE:'通过原申请',REJECT:'拒绝申请',ACCEPTED:'认可退货并登记处置',REFUSED:'整单拒收',RETRY_REFUND:'重试明确失败退款'} as Record<string,string>)[action]}}</h3><p class="notice">处理原申请金额；不会修改买家申请金额或直接声明退款完成。</p><template v-if="action==='ACCEPTED'"><p class="notice">认可退货退款与恢复可售库存分开。只有选择“可再售”才增加销售库存；待检、残次和报损同样保留退款义务。</p><ElFormItem v-for="a in materials.data.value?.allocations??[]" :key="unitKey(a.orderItemId,a.unitNo)" :label="`订单项 ${a.orderItemId} · 第${a.unitNo}件处置`" required><ElSelect v-model="dispositions[unitKey(a.orderItemId,a.unitNo)]" placeholder="请根据实物验收明确选择"><ElOption v-for="option in dispositionOptions" :key="option.value" :label="option.label" :value="option.value"/></ElSelect></ElFormItem></template><ElFormItem label="处理原因" required><ElInput v-model="reason" type="textarea" maxlength="500" :rows="3"/></ElFormItem><ElFormItem v-if="action==='REFUSED'" label="拒收证据" required><input type="file" class="upload-field" aria-label="上传拒收证据" :disabled="uploading" @change="upload"/><p class="field-hint">{{uploading?'正在上传…':`已上传 ${evidenceKeys.length} 份证据`}}</p></ElFormItem><Feedback :error="localError||command.error.value"/><ElButton native-type="submit" type="primary" :loading="command.busy.value" :disabled="uploading||!reason.trim()">确认处理</ElButton><ElButton @click="action=''">取消本次处理</ElButton></ElForm></template></ElDialog></template>
